import fs from 'node:fs';import vm from 'node:vm';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';
const assignment=process.argv[2];const target=process.argv[3];const a=JSON.parse(fs.readFileSync(assignment,'utf8'));const js=fs.readFileSync(a.workingJsAbsolute);const rawSha=crypto.createHash('sha256').update(js).digest('hex'),blob=crypto.createHash('sha1').update(Buffer.concat([Buffer.from('blob '+js.length+'\0'),js])).digest('hex');const cleanBlob=execFileSync('git',['hash-object','--path='+a.workingJsAbsolute,a.workingJsAbsolute],{encoding:'utf8'}).trim();const b={window:{}};vm.createContext(b);vm.runInContext(js.toString('utf8'),b,{filename:a.workingJsAbsolute,timeout:5000});const qs=b.window.questionBank||b.window.questions;if(!Array.isArray(qs)||qs.length!==24||qs.some((q,i)=>Number(q.id)!==i+1))throw new Error('CURRENT_QID_DENOMINATOR_MISMATCH');const assets=[];for(const r of a.requiredAssets){const abs=a.assetRootAbsolute+'\\'+r.ref.replaceAll('/','\\');const actual=crypto.createHash('sha256').update(fs.readFileSync(abs)).digest('hex');if(actual!==r.sha256)throw new Error('ASSET_HASH_MISMATCH:q'+r.qid);assets.push({qid:r.qid,ref:r.ref,sha256:actual})}const assetByQid=new Map(assets.map(x=>[x.qid,x]));const fields=['id','content','choices','image'];const rows=qs.map(q=>{const id=Number(q.id),asset=assetByQid.get(id)||null,image=q.image??null;if((asset?.ref??null)!==image)throw new Error('CURRENT_IMAGE_REF_MISMATCH:q'+id);const payload={id,content:q.content,choices:q.choices,image};const sorted=Object.fromEntries(Object.entries(payload).sort(([x],[y])=>x.localeCompare(y)));const payloadSha='sha256:'+crypto.createHash('sha256').update(JSON.stringify(sorted)).digest('hex');return{id,content:q.content,choices:q.choices,image,assetSha256:asset?.sha256??null,payloadSha256:payloadSha}});const out={schemaVersion:'JS_ARCHIVE_CODEX_STUDENT_ONLY_BUNDLE_V1',examUid:a.examUid,runId:a.runId,stage:'R2_HANDOFF',sourceArtifactRawSha256:rawSha,sourceArtifactBlobSha1:blob,gitCleanFilterBlobSha1:cleanBlob,qualityContractVersion:a.qualityContractVersion,executionLine:a.executionLine,questionCount:rows.length,qids:rows.map(r=>r.id),studentFields:fields,rows,assetManifest:assets};const forbidden=/^(?:answer|storedAnswer|solution|solutionImage|decisiveStep|Meta|difficulty|verdict|upstreamVerdict|reviewStatus)$/i;function scan(o,path='root'){if(Array.isArray(o)){o.forEach((v,i)=>scan(v,path+'['+i+']'));return}if(o&&typeof o==='object')for(const [k,v]of Object.entries(o)){if(forbidden.test(k))throw new Error('FORBIDDEN_FIELD:'+path+'.'+k);scan(v,path+'.'+k)}}scan(out);fs.writeFileSync(target,JSON.stringify(out,null,2)+'\n');const file=fs.readFileSync(target);console.log(JSON.stringify({path:target,bundleSha256:crypto.createHash('sha256').update(file).digest('hex'),artifactRawSha256:rawSha,artifactBlobSha1:blob,cleanFilterBlobSha1:cleanBlob,qids:rows.length,assetCount:assets.length,forbiddenFields:'NONE'},null,2));